BEGIN;

CREATE OR REPLACE FUNCTION public.asistente_detalle_factura(p_empresa_id text,p_factura_id text,p_sociedad_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public AS $$
DECLARE v_alcance uuid[]; v_permisos jsonb; v_ver_finanzas boolean; v_ver_tesoreria boolean; v_factura public.facturas%ROWTYPE; v_cxc public.cxc%ROWTYPE; v_resultado jsonb; v_omitidos text[]:=ARRAY[]::text[]; v_notas jsonb:='[]'::jsonb; v_cobros jsonb:='[]'::jsonb; v_gestiones jsonb:='[]'::jsonb; v_movimientos jsonb:='[]'::jsonb; v_hoy date:=(now() AT TIME ZONE 'America/Lima')::date;
BEGIN
 v_alcance:=public.asistente_autorizar(p_empresa_id,'facturacion',p_sociedad_id,true); v_permisos:=public.asistente_permisos_especiales(p_empresa_id); v_ver_finanzas:=coalesce((v_permisos->>'ver_finanzas')::boolean,false); v_ver_tesoreria:=v_ver_finanzas AND public.usuario_puede(p_empresa_id,'tesoreria','ver');
 IF NOT v_ver_finanzas THEN v_omitidos:=v_omitidos||ARRAY['subtotal','igv','total','monto_retencion','monto_detraccion','monto_neto_cobrable','cxc','notas_vinculadas','cobros_recientes','gestiones_cobranza']::text[]; END IF;
 IF NOT v_ver_tesoreria THEN v_omitidos:=v_omitidos||ARRAY['movimientos_tesoreria']::text[]; END IF;
 SELECT x.* INTO v_factura FROM public.facturas x WHERE x.empresa_id=p_empresa_id AND x.id=p_factura_id AND (v_alcance IS NULL OR x.sociedad_id=ANY(v_alcance));
 IF NOT FOUND THEN RETURN jsonb_build_object('encontrado',false,'campos_omitidos_por_permiso',to_jsonb(v_omitidos)); END IF;
 SELECT x.* INTO v_cxc FROM public.cxc x WHERE x.empresa_id=p_empresa_id AND x.factura_id=v_factura.id AND (v_alcance IS NULL OR x.sociedad_id=ANY(v_alcance)) ORDER BY x.fecha_emision DESC NULLS LAST,x.id LIMIT 1;
 SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',left(n.id,80),'numero',left(n.numero,80),'tipo_documento',n.tipo_documento,'estado',n.estado,'fecha_emision',n.fecha_emision,'moneda',upper(coalesce(nullif(n.moneda,''),'PEN')),'motivo',left(coalesce(n.motivo,n.motivo_codigo),80),'total',CASE WHEN v_ver_finanzas THEN n.total END)) ORDER BY n.fecha_emision DESC NULLS LAST,n.id),'[]'::jsonb) INTO v_notas FROM (SELECT x.* FROM public.facturas x WHERE x.empresa_id=p_empresa_id AND x.factura_origen_id=v_factura.id AND (v_alcance IS NULL OR x.sociedad_id=ANY(v_alcance)) ORDER BY x.fecha_emision DESC NULLS LAST,x.id LIMIT 10) n;
 IF v_ver_finanzas AND v_cxc.id IS NOT NULL THEN
  SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',left(x.id,80),'fecha_cobro',x.fecha_cobro,'monto_capital',x.monto_capital,'monto_mora',x.monto_mora,'medio_pago',x.medio_pago,'cuenta_bancaria',left(x.cuenta_bancaria,50),'numero_operacion',left(x.numero_operacion,50),'notas',left(x.notas,80))) ORDER BY x.fecha_cobro DESC,x.creado_en DESC),'[]'::jsonb) INTO v_cobros FROM (SELECT z.* FROM public.cobros_cxc z WHERE z.empresa_id=p_empresa_id AND z.cxc_id=v_cxc.id ORDER BY z.fecha_cobro DESC,z.creado_en DESC LIMIT 10) x;
  SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('tipo_gestion',left(x.tipo_gestion,40),'resultado',left(x.resultado,60),'fecha_gestion',x.fecha_gestion,'fecha_proxima_accion',x.fecha_proxima_accion,'fecha_acordada_pago',x.fecha_acordada_pago,'notas',left(x.notas,80))) ORDER BY x.fecha_gestion DESC,x.creado_en DESC),'[]'::jsonb) INTO v_gestiones FROM (SELECT z.* FROM public.gestion_cobranza z WHERE z.empresa_id=p_empresa_id AND z.cxc_id=v_cxc.id ORDER BY z.fecha_gestion DESC,z.creado_en DESC LIMIT 5) x;
  IF v_ver_tesoreria THEN SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',left(x.id,80),'tipo',left(x.tipo,20),'descripcion',left(x.descripcion,70),'monto',x.monto,'moneda',upper(coalesce(nullif(x.moneda,''),'PEN')),'fecha',x.fecha,'cuenta_bancaria',left(x.cuenta_bancaria,50),'referencia',left(x.referencia,100),'estado',x.estado)) ORDER BY x.fecha DESC,x.created_at DESC),'[]'::jsonb) INTO v_movimientos FROM (SELECT z.* FROM public.movimientos_tesoreria z WHERE z.empresa_id=p_empresa_id AND z.vinculo_tipo='cxc' AND z.vinculo_id=v_cxc.id AND z.empresa_id=v_cxc.empresa_id AND (v_alcance IS NULL OR v_cxc.sociedad_id=ANY(v_alcance)) ORDER BY z.fecha DESC,z.created_at DESC LIMIT 10) x; END IF;
 END IF;
 SELECT jsonb_strip_nulls(jsonb_build_object('encontrado',true,'id',left(qf.id,80),'numero',left(qf.numero,80),'tipo_documento',qf.tipo_documento,'estado',qf.estado,'fecha_emision',qf.fecha_emision,'fecha_vencimiento',qf.fecha_vencimiento,'moneda',upper(coalesce(nullif(qf.moneda,''),'PEN')),'glosa',left(qf.glosa,160),'concepto',left(qf.concepto,160),'motivo',left(coalesce(qf.motivo,qf.motivo_codigo),80),'cliente',left(coalesce(ct.nombre_comercial,ct.razon_social),100),'os_numero',left(os.numero,60),'subtotal',CASE WHEN v_ver_finanzas THEN qf.subtotal END,'igv',CASE WHEN v_ver_finanzas THEN qf.igv END,'total',CASE WHEN v_ver_finanzas THEN qf.total END,'monto_retencion',CASE WHEN v_ver_finanzas THEN qf.monto_retencion END,'monto_detraccion',CASE WHEN v_ver_finanzas THEN qf.monto_detraccion END,'monto_neto_cobrable',CASE WHEN v_ver_finanzas THEN qf.monto_neto_cobrable END,'cxc',CASE WHEN v_ver_finanzas AND v_cxc.id IS NOT NULL THEN jsonb_build_object('vencimiento',v_cxc.fecha_vencimiento,'saldo',greatest(coalesce(v_cxc.saldo,0)-coalesce(v_cxc.monto_retencion,0),0),'pagado',v_cxc.monto_pagado,'estado',v_cxc.estado,'dias_mora',CASE WHEN lower(coalesce(v_cxc.estado,'')) NOT IN ('cobrada','pagada','anulada','cancelada') THEN greatest(v_hoy-v_cxc.fecha_vencimiento,0) ELSE 0 END) END,'notas_vinculadas',CASE WHEN v_ver_finanzas THEN v_notas END,'cobros_recientes',CASE WHEN v_ver_finanzas AND v_cxc.id IS NOT NULL THEN v_cobros END,'gestiones_cobranza',CASE WHEN v_ver_finanzas AND v_cxc.id IS NOT NULL THEN v_gestiones END,'movimientos_tesoreria',CASE WHEN v_ver_tesoreria AND v_cxc.id IS NOT NULL THEN v_movimientos END,'campos_omitidos_por_permiso',to_jsonb(v_omitidos))) INTO v_resultado FROM public.facturas qf LEFT JOIN public.cuentas ct ON ct.empresa_id=qf.empresa_id AND ct.id=qf.cuenta_id LEFT JOIN public.os_clientes os ON os.empresa_id=qf.empresa_id AND os.id=qf.os_cliente_id WHERE qf.empresa_id=p_empresa_id AND qf.id=p_factura_id AND (v_alcance IS NULL OR qf.sociedad_id=ANY(v_alcance));
 RETURN v_resultado;
END $$;

CREATE OR REPLACE FUNCTION public.asistente_resumen_financiero(p_empresa_id text,p_sociedad_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public AS $$
DECLARE cxc jsonb; cxp jsonb; tes jsonb; caja jsonb; r jsonb; omitidas text[]:=ARRAY[]::text[]; campos_omitidos text[]:=ARRAY[]::text[]; campos_unicos text[]; hoy date:=(now() AT TIME ZONE 'America/Lima')::date;
BEGIN
 BEGIN r:=public.asistente_resumen_cxc(p_empresa_id,p_sociedad_id,NULL); SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('moneda',x->>'moneda','total',x->'total_por_cobrar','vencido',x->'vencido','cantidad',x->'cantidad','cantidad_vencida',x->'cantidad_vencida')) ORDER BY x->>'moneda'),'[]'::jsonb) INTO cxc FROM jsonb_array_elements(coalesce(r->'por_moneda','[]'::jsonb)) x; SELECT coalesce(array_agg(DISTINCT 'cxc.'||campo),'{}'::text[]) INTO campos_omitidos FROM jsonb_array_elements_text(coalesce(r->'campos_omitidos_por_permiso','[]'::jsonb)) campo;
 EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'Falta permiso de lectura%' THEN omitidas:=array_append(omitidas,'cxc'); ELSE RAISE; END IF; END;
 BEGIN r:=public.asistente_resumen_cxp(p_empresa_id,p_sociedad_id,NULL); SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('moneda',x->>'moneda','total',x->'total_por_pagar','vencido',x->'vencido','cantidad',x->'cantidad','cantidad_vencida',x->'cantidad_vencida')) ORDER BY x->>'moneda'),'[]'::jsonb) INTO cxp FROM jsonb_array_elements(coalesce(r->'por_moneda','[]'::jsonb)) x; SELECT campos_omitidos||coalesce(array_agg(DISTINCT 'cxp.'||campo),'{}'::text[]) INTO campos_omitidos FROM jsonb_array_elements_text(coalesce(r->'campos_omitidos_por_permiso','[]'::jsonb)) campo;
 EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'Falta permiso de lectura%' THEN omitidas:=array_append(omitidas,'cxp'); ELSE RAISE; END IF; END;
 BEGIN r:=public.asistente_resumen_tesoreria(p_empresa_id,p_sociedad_id,NULL); SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('moneda',x->>'moneda','saldo_total',x->'saldo_total')) ORDER BY x->>'moneda'),'[]'::jsonb) INTO tes FROM jsonb_array_elements(coalesce(r->'por_moneda','[]'::jsonb)) x; SELECT campos_omitidos||coalesce(array_agg(DISTINCT 'tesoreria.'||campo),'{}'::text[]) INTO campos_omitidos FROM jsonb_array_elements_text(coalesce(r->'campos_omitidos_por_permiso','[]'::jsonb)) campo; tes:=jsonb_build_object('por_moneda',tes,'movimientos_del_mes',coalesce(r->'movimientos_del_mes','[]'::jsonb));
 EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'Falta permiso de lectura%' THEN omitidas:=array_append(omitidas,'tesoreria'); ELSE RAISE; END IF; END;
 BEGIN r:=public.asistente_resumen_caja_chica(p_empresa_id,p_sociedad_id,NULL); SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('moneda',x->>'moneda','saldo_total',x->'saldo_total')) ORDER BY x->>'moneda'),'[]'::jsonb) INTO caja FROM jsonb_array_elements(coalesce(r->'por_moneda','[]'::jsonb)) x; SELECT campos_omitidos||coalesce(array_agg(DISTINCT 'caja_chica.'||campo),'{}'::text[]) INTO campos_omitidos FROM jsonb_array_elements_text(coalesce(r->'campos_omitidos_por_permiso','[]'::jsonb)) campo;
 EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'Falta permiso de lectura%' THEN omitidas:=array_append(omitidas,'caja_chica'); ELSE RAISE; END IF; END;
 SELECT coalesce(array_agg(DISTINCT campo ORDER BY campo),'{}'::text[]) INTO campos_unicos FROM unnest(campos_omitidos) campo;
 RETURN jsonb_build_object('fecha_corte',hoy,'cxc_por_moneda',cxc,'cxp_por_moneda',cxp,'tesoreria',tes,'caja_chica_por_moneda',caja,'secciones_omitidas_por_permiso',to_jsonb(omitidas),'campos_omitidos_por_permiso',to_jsonb(campos_unicos));
END $$;

DO $$
DECLARE d text; a text; b text; n integer;
BEGIN
 d:=pg_get_functiondef('public.asistente_buscar_facturas(text,uuid,text,text,text,date,date,boolean,integer,numeric,numeric,numeric)'::regprocedure);
 a:=$a$jsonb_build_object('numero',b.numero,'cliente',b.cliente,'tipo_documento',b.tipo_documento,'estado',b.estado,$a$; b:=$b$jsonb_build_object('id',b.id,'numero',b.numero,'cliente',b.cliente,'tipo_documento',b.tipo_documento,'estado',b.estado,$b$;
 n:=(length(d)-length(replace(d,a,'')))/length(a); IF n<>1 THEN RAISE EXCEPTION 'Ancla de buscar_facturas: esperada 1, encontrada %',n; END IF; d:=replace(d,a,b); IF position('''id'',b.id' in d)=0 THEN RAISE EXCEPTION 'No se añadió id a buscar_facturas'; END IF; EXECUTE d;

 d:=pg_get_functiondef('public.asistente_resumen_cxc(text,uuid,text)'::regprocedure);
 a:=$a$END)) ORDER BY g.mon),'[]'::jsonb)$a$;
 b:=$b$END,'principales_morosos',CASE WHEN m THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('cliente',z.cli,'monto_vencido',round(z.s,2),'documentos_vencidos',z.k,'mora_maxima_dias',z.md) ORDER BY z.s DESC),'[]'::jsonb) FROM (SELECT b2.cli,sum(b2.sn) s,count(*) k,max(b2.mora) md FROM b b2 WHERE b2.mon=g.mon AND b2.mora>0 GROUP BY b2.cli ORDER BY sum(b2.sn) DESC LIMIT 5) z) END,'mas_antiguos',CASE WHEN m THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('cliente',z.cli,'monto_vencido',round(z.s,2),'documentos_vencidos',z.k,'mora_maxima_dias',z.md) ORDER BY z.md DESC),'[]'::jsonb) FROM (SELECT b2.cli,sum(b2.sn) s,count(*) k,max(b2.mora) md FROM b b2 WHERE b2.mon=g.mon AND b2.mora>0 GROUP BY b2.cli ORDER BY max(b2.mora) DESC LIMIT 5) z) END)) ORDER BY g.mon),'[]'::jsonb)$b$;
 n:=(length(d)-length(replace(d,a,'')))/length(a); IF n<>1 THEN RAISE EXCEPTION 'Ancla CxC: esperada 1, encontrada %',n; END IF; d:=replace(d,a,b); IF position('principales_morosos' in d)=0 OR position('mas_antiguos' in d)=0 THEN RAISE EXCEPTION 'Faltan claves nuevas CxC'; END IF;
 a:=$a$ARRAY['montos','principales_clientes']::text[]$a$; b:=$b$ARRAY['montos','principales_clientes','principales_morosos','mas_antiguos']::text[]$b$; n:=(length(d)-length(replace(d,a,'')))/length(a); IF n<>1 THEN RAISE EXCEPTION 'Ancla de permisos CxC: esperada 1, encontrada %',n; END IF; d:=replace(d,a,b); EXECUTE d;

 d:=pg_get_functiondef('public.asistente_resumen_cxp(text,uuid,text)'::regprocedure);
 a:=$a$END)) ORDER BY g.mon),'[]'::jsonb)$a$;
 b:=$b$END,'principales_proveedores_vencidos',CASE WHEN m THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('proveedor',z.prov,'monto_vencido',round(z.s,2),'documentos_vencidos',z.k,'mora_maxima_dias',z.md) ORDER BY z.s DESC),'[]'::jsonb) FROM (SELECT b2.prov,sum(b2.sn) s,count(*) k,max(b2.mora) md FROM b b2 WHERE b2.mon=g.mon AND b2.mora>0 GROUP BY b2.prov ORDER BY sum(b2.sn) DESC LIMIT 5) z) END,'mas_antiguos',CASE WHEN m THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('proveedor',z.prov,'monto_vencido',round(z.s,2),'documentos_vencidos',z.k,'mora_maxima_dias',z.md) ORDER BY z.md DESC),'[]'::jsonb) FROM (SELECT b2.prov,sum(b2.sn) s,count(*) k,max(b2.mora) md FROM b b2 WHERE b2.mon=g.mon AND b2.mora>0 GROUP BY b2.prov ORDER BY max(b2.mora) DESC LIMIT 5) z) END)) ORDER BY g.mon),'[]'::jsonb)$b$;
 n:=(length(d)-length(replace(d,a,'')))/length(a); IF n<>1 THEN RAISE EXCEPTION 'Ancla CxP: esperada 1, encontrada %',n; END IF; d:=replace(d,a,b); IF position('principales_proveedores_vencidos' in d)=0 OR position('mas_antiguos' in d)=0 THEN RAISE EXCEPTION 'Faltan claves nuevas CxP'; END IF;
 a:=$a$ARRAY['montos','principales_proveedores']::text[]$a$; b:=$b$ARRAY['montos','principales_proveedores','principales_proveedores_vencidos','mas_antiguos']::text[]$b$; n:=(length(d)-length(replace(d,a,'')))/length(a); IF n<>1 THEN RAISE EXCEPTION 'Ancla de permisos CxP: esperada 1, encontrada %',n; END IF; d:=replace(d,a,b); EXECUTE d;
END $$;

REVOKE ALL ON FUNCTION public.asistente_detalle_factura(text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.asistente_detalle_factura(text,text,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.asistente_resumen_financiero(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.asistente_resumen_financiero(text,uuid) TO authenticated;

DO $$
DECLARE f oid; d text;
BEGIN
 IF to_regprocedure('public.asistente_detalle_factura(text,text,uuid)') IS NULL OR to_regprocedure('public.asistente_resumen_financiero(text,uuid)') IS NULL THEN RAISE EXCEPTION 'Falta función nueva'; END IF;
 FOREACH f IN ARRAY ARRAY[to_regprocedure('public.asistente_detalle_factura(text,text,uuid)')::oid,to_regprocedure('public.asistente_resumen_financiero(text,uuid)')::oid] LOOP
  IF NOT has_function_privilege('authenticated',f,'EXECUTE') OR has_function_privilege('anon',f,'EXECUTE') OR EXISTS (SELECT 1 FROM aclexplode(coalesce((SELECT proacl FROM pg_proc WHERE oid=f),acldefault('f',(SELECT proowner FROM pg_proc WHERE oid=f)))) x WHERE x.grantee=0 AND x.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Privilegios incorrectos para %',f::regprocedure; END IF;
 END LOOP;
 d:=pg_get_functiondef('public.asistente_buscar_facturas(text,uuid,text,text,text,date,date,boolean,integer,numeric,numeric,numeric)'::regprocedure); IF position('''id'',b.id' in d)=0 THEN RAISE EXCEPTION 'Falta id en facturas'; END IF;
 d:=pg_get_functiondef('public.asistente_resumen_cxc(text,uuid,text)'::regprocedure); IF position('principales_morosos' in d)=0 OR position('mas_antiguos' in d)=0 THEN RAISE EXCEPTION 'Faltan claves CxC'; END IF;
 d:=pg_get_functiondef('public.asistente_resumen_cxp(text,uuid,text)'::regprocedure); IF position('principales_proveedores_vencidos' in d)=0 OR position('mas_antiguos' in d)=0 THEN RAISE EXCEPTION 'Faltan claves CxP'; END IF;
END $$;

COMMIT;
